    "body": "یوسف گم‌گشته بازآید به کنعان، غم مخور\nکلبه‌ی احزان شود روزی گلستان، غم مخور\nای دلِ غمدیده حالت بِه شود، دل بد مکن\nوین سرِ شوریده بازآید به سامان غم مخور\nگر بهارِ عمر باشد باز بر تختِ چمن\nچترِ گل در سر کشی، ای مرغِ خوشخوان غم مخور\nدورِ گردون گر دو روزی بر مرادِ ما نرفت\nدائماً یکسان نباشد حالِ دوران غم مخور\nهان مَشو نومید چون واقِف نِه‌ای از سِرِّ غیب\nباشد اندر پرده، بازی‌هایِ پنهان غم مخور\nای دل اَر سیلِ فنا بنیادِ هستی بَرکَنَد\nچون تو را نوح است کشتیبان، زِ طوفان غم مخور\nدر بیابان گر به شوقِ کعبه خواهی زد قدم\nسرزنش‌ها گر کُنَد خارِ مُغیلان غم مخور\nگرچه منزل بس خطرناک است و مقصد بس بعید\nهیچ راهی نیست کآن را نیست پایان، غم مخور."
