    "section": "poems",
    "tags": [
      0,
      0
    ],
    "author": "فاضل‌ نظری",
    "body": "گر جوابم را نمی‌گویی جوابم کن به قهر\nگاه یک دشنام از صدها دعا شیرین‌تر است."
