    "body": "حافظا دیدی که کنعان دلم بی ماه شد\nعاقبت با اشک غم کوه امیدم آه شد\nگفته بودی یوسف گمگشته باز آید ولی\nیوسف من تا قیامت هم نشین چاه شد"
