    "author": "زهرا عسگری",
    "body": "همان بهتر نمیدانی، چرا حالم پریشان است\n  همان بهتر نمی‌دانی که دنیایم چه ویران است\nمرا با خنده می بینی، تصور میکنی شادم\n  همان بهتر نمی دانی، که غم‌هایم فراوان است"
