    "tags": [
      0,
      0
    ],
    "author": "فاضل نظری",
    "body": "با آنکه بی‌دلیل رها می‌کنی مرا\nآنقدر عاشقم که نمی‌پرسمت چرا؟\nخون می‌خوریم در غم و حرفی نمی‌زنیم؛\n             ما عاشق تو ایم همین است ماجرا."
