    "body": "گر به دولت برسی، مست نگردی، مردی. \nگر به ذلت برسی،  پست نگردی، مردی. \nاهل عالم همه بازیچه دست هوس اند؛ \nگر تو بازیچه این دست نگردی، مردی."
