    "author": "",
    "body": "از خانه‌ام تا خانه‌ات راهی نیست\nو این نزدیکی\nدوری‌مان را بیشتر می‌کند \nوقتی که گوش‌هایت\nبه وسعت حرف‌هایم نیست \nتنها می‌شوم\nچرا مرا چنان لگدکوب نمی‌کنی \nکه با خیال تخت \nدر دسترس نباشم؟\nو یا چنان بغل نمیکنی که با تمام تن\nشاعرت باشم؟"
