    "body": "بارالها\nاز كوي تو بيرون نشود پاي خيالم\nنكند فرق به حالم \nچه براني، چه بخوانی\nچه به اوجم برسانی\nچه به خاكم بكشانی\nنه من آنم كه برنجم\nنه تو آني كه برانی\nنه من آنم كه ز فيض نگهت چشم بپوشم\nنه تو آني كه گدا را ننوازی به نگاهی\nدر اگر باز نگردد\nنروم باز به جايی\nپشت ديوار نشينم چو گدا بر سر راهی\nكس به غير از تو نخواهم\nچه بخواهی چه نخواهی\nباز كن در كه جز اين خانه مرا نيست پناهی"
