    "body": "یا رب مرا یاری بده، تا سخت آزارش کنم\nهجرش دهم، زجرش دهم، خوارش کنم، زارش کنم\nاز بوسه های آتشین، وز خنده های دلنشین\nصد شعله در جانش زنم، صد فتنه در کارش کنم"
