    "section": "poems",
    "tags": [
      1,
      0
    ],
    "author": "ادیب نیشابوری‌",
    "body": "جز تو یاری نگرفتیم و نخواهیم گرفت،\nبر همان عهد که بودیم، بر آنیم هنوز\nبه امید تو شب خویش به پایان آریم\nآن جفا دیده که بودیم، همانیم هنوز."
