    "section": "poems",
    "tags": [
      1,
      0
    ],
    "author": "مولوی",
    "body": "هر روز دلم در غم تو زارتر است\nوز من دل بی‌رحم تو بی‌زارتر است\nبگذاشتی‌ام، غمت بنگذاشت مرا \nحقّا که غمت از تو وفادارتر است"
