    "id": "telegram-2155",
    "section": "poems",
    "tags": [
      0,
      0
    ],
    "author": "شیرازی",
    "body": "آن صبر که در حوصله ی غیر نگنجد\nدر ماست که خارج بود از طاقت ایوب."
