    "id": "telegram-2158",
    "section": "poems",
    "tags": [
      0,
      0
    ],
    "author": "ابتهاج",
    "body": "گر مرد رهی غم مخور از دوری و دیری\nدانی که رسیدن هنر گام زمان است."
