    "author": "فریدون ‌مشیری",
    "body": "بگذار تا ببوسمت ای نوش‌خند صبح\nبگذار تا بنوشمت ای چشمهٔ شراب\nبیمار خنده‌های تواَم بیش‌تر بخند\nخورشید آرزوی منی گرم‌تر بتاب."
