    "author": "عماد ‌خراسانی",
    "body": "ای روزگار وصل، ز یادم دگر برو\nاکنون که شام هجر مرا بی‌خبر گرفت\nای مرغِ پرشکسته دل من، دگر بمیر\nطاووس مست من چو از این باغ پر گرفت."
