    "section": "poems",
    "tags": [
      0,
      0
    ],
    "author": "صائب ‌تبریزی",
    "body": "ز همراهان کسی نگرفت شمعی پیش راه من\nبه برق تیشه زین ظلمت برون چون کوهکن رفتم."
