    "author": "مهدی جوینی",
    "body": "آن بار گران رفت و دگر بار شما نیست\nدل کندنم این بار به اصرار شما نیست\nمن رود پریشان و تو دریای غروری\nدیگر به سرم خواهش دیدار شما نیست."
