    "author": "باباطاهر",
    "body": "فلک! در قصد آزارُم چرایی؟\nگُلُم گر نیستی خارُم چرایی؟\nتو که باری زِ دوشُم برنداری!\nمیونِ بار، سربارُم چرایی؟"
