    "section": "poems",
    "tags": [
      0,
      0
    ],
    "author": "",
    "body": "می‌نشینی شعر می‌خوانی و من محو صدایت\nمی‌نشینم دست زیر چانه پای حرف‌هایت\nشوق داری از غزل‌های قدیمی هم بخوانی\nدوست دارم بشنوم تا صبح از حال و هوایت\nمی‌برد هر واژه ما را تا خیال دوردستی\nشعر می‌خوانی برایم اشک می‌ریزم برایت\nاز چه می‌ترسانی‌ام ای عشق از اندوه فردا؟\nهرچه باداباد می‌دانی که می‌مانم به پایت."
