    "author": "ظهیر ‌فاریابی",
    "body": "دوش این خِرَدم نصیحتی پنهان گفت\nدر گوش دلم گفت و دلم با جان گفت\nبا کس غم دل مگوی زیرا که نماند\nیک دوست که با او غم دل بتوان گفت"
