    "author": "فاضل نظری",
    "body": "باد روشن می‌کند خاکستر افسرده را\nشعله‌ورتر می‌شوم هرقدر خاموشم کنی\nتلخی و شیرینی دشنام و لبخندت یکی‌ست\nباز کن لب تا به سحر عشق مدهوشم کنی."
