    "author": "مهدخت نبوی",
    "body": "هر چند که تلخ اما حقیقت دارد\nاین ذات بشر به خشم عادت دارد\nبا هر که محبتم ز حد افزون شد\nدیدم که تمایل به عداوت دارد."
