    "id": "telegram-3150",
    "section": "poems",
    "tags": [
      0,
      0
    ],
    "author": "مقیمی",
    "body": "گذرِ عمر به شیدایی ما افزوده‌ست\nرنجِ دنیا به شکیبایی ما افزوده‌ست\nپایمالِ همه چون قالیِ کرمان شده‌ایم\nطعنه خلق به زیبایی ما افزوده‌ست\nهرچه می‌خواست زِ تنهاییِ خود کاست، ولی\nتا توانست به تنهاییِ ما افزوده‌ست\nوصفِ زیباییِ او را همه‌جا می‌شنوم\nهرکجا رفته به رسواییِ ما افزوده‌ست\nچشمِ او قلبِ مرا برده به تاراج، ولی\nگوهرِ اشک به بیناییِ ما افزوده‌ست"
