    "body": "چه شد که بار دگر یاد آشنا کردی\nچه شد که شیوه بیگانگی رها کردی\nبه قهر رفتن و جور و جفا شعار تو بود\nچه شد که بر سر مهر آمدی وفا کردی؟"
