    "body": "نمی‌گویم همین شب‌های ابرآلود برگردی\nتو فرصت داری اصلاً تا ابد تا زود برگردی\nتو فرصت داری از هر جای این تقویم بی‌تاریخ\nبدون هیچ مرز، ای عشق نامحدود برگردی."
