    "tags": [
      0,
      0
    ],
    "author": "فاضل نظری",
    "body": "من شیشه کوهم، اما از وسط تا خورده‌ام\nتو تصور می‌کنی، چوبِ خدا را خورده‌ام\nنه خیال بد مکن، چوب خدا اینگونه نیست\nمن هر آنچه خورده‌ام، از دست دنیا خورده‌ام\nقطره‌ام اما هزاران رود جاری در من است\nغرق در دشواری‌ام، انگار دریا خورده‌ام\nدائماً در حال تغییرم، بپرس از آینه\nبارها از دیدن تصویرِ خود جا خورده‌ام."
