    "body": "درمان درد عشق اگر در ندیدن است\nپس رود از چه در تب‌وتاب رسیدن است\nمی‌سوزم از فراق ولی دم نمی‌زنم\nتنها گناه شب‌پره بالاپریدن است\nاین عشق ریشه‌دارتر است از درخت‌ها\nای باغبان! خلاصی‌ات از من بریدن است\nدر نیمه‌راه عشق به عقل اعتماد ما\nدر راه سیل بر سر هم سنگ‌چیدن است\nهرچند از سکوت تو بدتر سکوت توست\nاما سکوت خوب‌تر از نه ‌شنیدن است."
