    "body": "تو مرا آزردی\nکه خودم کوچ کنم از شهرت،\nتو خیالت راحت\nمیروم از قلبت،\nمی‌شوم دورترین خاطره در شب‌هایت\nتو به من میخندی\nو به خود میگویی: باز می‌آید و میسوزد از این عشق ولی\nبرنمی‌گردم، نه\nمیروم آنجا که دلی بهر دلی تب دارد.\nعشق زیباست و حرمت دارد."
