    "body": "ﻣﻦ ﺍﺯ ﺁﻏﺎﺯ نمیﺗﺮﺳﻢ \nﻣﻦ ﺍﺯ ﭘﺮﻭﺍﺯ نمیﺗﺮﺳﻢ \nﻣﻦ ﺍﺯ ﺁﻏﺎﺯ ﯾﮏ ﭘﺮﻭﺍﺯ ﺑﯽ ﺍﺣﺴﺎﺱ ﻣﯽ ﺗﺮﺳﻢ."
