    "id": "telegram-4079",
    "section": "poems",
    "tags": [
      0,
      0
    ],
    "author": "",
    "body": "دیدمت رفتی و داغت جگرم را سوزاند\nفکر بی هم نفسی با تو سرم را سوزاند\nعقل از نیمه‌ی معمولی من رد شد و رفت\nعشق هم نیمه‌ی دیوانه‌ترم را سوزاند\nابرها آمده بودند نفس تازه کنم\nرعد و برقی همه‌ی برگ و برم را سوزاند\nمن گنجشک کجا جرئت پروانه کجا\nخواستم گرم شوم شعله پرم را سوزاند."
