    "body": "حرف هایم بیشو من کم‌حرف‌تر هی میشوم \nدرد هایم بیشتر ، من مرد تر هی میشوم \nمن تمام عمر دنبال رفیقان بوده ام \nحال با هرکه کنارم سرد تر هی‌میشوم\nآبیِ کم رنگ بودم با نشاط و زنده من \nمشکی‌ام حالا و هی پر رنگ‌تر من‌میشوم\nبغض میکردم اگر گنجشک بالش میشکست\nگرگ گشتم وحشی‌و دل سنگ‌تر من میشوم \nدادِ اسلامم که گوش شهر را کر کرده بود \nحال مستم هر شبو هی مست‌تر من میشوم\nاز نگاهم پست بود هرکس که بوی دود داشت \nروز ها پاکت به پاکت پست تر من میشوم."
