    "section": "poems",
    "tags": [
      0,
      0
    ],
    "author": "فرهاد شریفی",
    "body": "دلِ من پیش تو معنای بغل را فهمید\nقدر این فاصله‌ی حداقل را فهمید\nبا دو تا بوسه‌ی شیرین که به لب‌های تو زد\nمزه‌ی واقعی شهد و عسل را فهمید."
