    "author": "",
    "body": "ناز بوی من مبادا نا کسان بویت کنند\nبا بدان کمتر نشین ترسم که بد خویت کنند\nبوی عطر زلف تو دیوانه سازد عالمی\nبشکند دستی که قصد لمس گیسویت کند."
