    "body": "ﺧﺎﻧﻪ ﺩﻝ ﺟﺎﯼ ﻫﺮ ﺑﯿﮕﺎﻧﻪ ﻧﯿﺴﺖ\nﮐﻮﯼ ﻣﺠﻨﻮﻥ ﺟﺎﯼﻫﺮ ﺩﯾﻮﺍﻧﻪ ﻧﯿﺴﺖ \nﻗﻠﺐ ﻟﯿﻠﯽ ﺑﻪ ﻣﺠﻨﻮﻥ ﺧﻮﺷﺘﺮ اﺳﺖ \nﻏﯿﺮ ﻟﯿﻠﯽ ﮐﺲ ﻻﯾﻖ ﺍﯾﻦ ﺧﺎﻧﻪ ﻧﯿﺴﺖ."
